  const root = newTable()
  let cur = root
  let curPath = ''
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.eol()) return
      if (L.c === '[') {
        L.i++
        const aot = L.c === '['
        if (aot) L.i++
        L.ws()
        const names = parseDotted(L)
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
