  const kids = n.t === 'table' ? sortedEntries(n).map(([k, v]) => [join(path, k), v])
    : n.t === 'array' ? n.items.map((v, i) => [path + '[' + i + ']', v]) : []
  for (const [p, v] of kids) {
    out.push(p + ' ' + v.t)
    keys(v, p, out)
  }
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'json' && mode[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
