  const root = parse(readFileSync(0, 'utf8'))
  if (mode[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keys(root, '', out)
    if (out.length) process.stdout.write(out.join('\n') + '\n')
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exit(2)
}
